31	  spawnSync(binary(), ['server', 'reload-config'], { encoding: 'utf8', timeout: 5000, windowsHide: true });
32	}
33	
34	// Herdr's own verdict on the config file as it stands. `parses` is the one
35	// that matters: on a parse error Herdr says so and falls back to defaults,
36	// which takes every plugin down; an unknown key is only ignored, and the
37	// exit code is 1 for both, so the exit code alone would refuse a file that
38	// works. A Herdr with no such command counts as parsing — the check is a
39	// safety net, not a gate. `run` is for tests only.
40	function configCheck(run = spawnSync) {
41	  const result = run(binary(), ['config', 'check'], { encoding: 'utf8', timeout: 5000, windowsHide: true });
42	  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`.trim();
43	  if (result.error || result.status === null) return { parses: true, ok: true, output };
44	  return { parses: !/config parse error/.test(output), ok: result.status === 0, output };
45	}
46	
