48	// "failed (exit 1)" and files the output in the plugin log, which someone
49	// installing for the first time does not know to read (#22). Best effort:
50	// a Herdr without the command loses nothing but the toast.
51	function notify(title, body) {
52	  spawnSync(binary(), ['notification', 'show', title, '--body', body], {
53	    encoding: 'utf8',
54	    timeout: 5000,
55	    windowsHide: true,
56	  });
57	}
58	
59	// Returns the parsed JSON body, or null when the call failed for any reason.
60	// Callers treat a failure as "no data" rather than an error: a plugin that
61	// throws on a transient socket hiccup is worse than one that skips a frame.
62	function call(...args) {
63	  try {
64	    const result = spawnSync(binary(), args, {
65	      encoding: 'utf8',
66	      timeout: TIMEOUT_MS,
67	      windowsHide: true,
68	      maxBuffer: 8 * 1024 * 1024,
69	    });
70	    if (result.status !== 0 || !result.stdout?.trim()) return null;
71	    return JSON.parse(result.stdout);
72	  } catch {
73	    return null;
74	  }
75	}
