77	function panes() {
78	  return call('pane', 'list')?.result?.panes ?? [];
79	}
80	
81	function pane(paneId) {
82	  return call('pane', 'get', paneId)?.result?.pane ?? null;
83	}
84	
85	// Null on failure, not an empty list: to a caller tracking liveness those are
86	// opposite claims. An empty list says every agent is gone — act on it — while
87	// a failed call says nothing, and acting on nothing-as-empty once wiped every
88	// activity stamp and cleared every token over one timed-out list during a
89	// config reload.
90	function agents() {
91	  return call('agent', 'list')?.result?.agents ?? null;
92	}
93	
94	function tabs() {
95	  return call('tab', 'list')?.result?.tabs ?? [];
96	}
97	
98	function workspaces() {
99	  return call('workspace', 'list')?.result?.workspaces ?? [];
100	}
101	
102	// The foreground process's real working directory.
103	//
104	// Herdr's own `pane.cwd` only knows where the pane was launched — the Windows
105	// support matrix lists live cwd as partial — but the process table still has
106	// the truth for anything that actually chdir()s, which covers every agent CLI
107	// and bash. This is agent-agnostic, so no per-CLI hook is needed for the path.
108	function paneProcessCwd(paneId) {
109	  if (!paneId) return null;
110	  const foreground = call('pane', 'process-info', '--pane', paneId)?.result?.process_info?.foreground_processes?.[0];
111	  return foreground?.cwd ?? null;
112	}
113	
114	// Width of the tab row, in columns.
115	//
116	// The status area shares that row with the tabs and their controls, and Herdr
117	// drops the *entire* status area when it does not fit rather than truncating
118	// it — so a line that is one column too long simply disappears. `pane layout`
119	// reports the pane area as `{x, y, width, height}`; x is the sidebar width and
120	// width is what the tab row has to work with.
121	function tabRowWidth(paneId) {
122	  if (!paneId) return null;
123	  const area = call('pane', 'layout', '--pane', paneId)?.result?.layout?.area;
124	  return typeof area?.width === 'number' ? area.width : null;
125	}
126	
127	// Async socket twins of the four list reads. Every CLI call is a process
128	// spawn; the daemon reads the agent list up to seven times a second while
129	// something animates, which made the read path the largest remaining spawn
130	// source once the writes moved to the socket. Transport failure falls back to
131	// one CLI attempt, preserving each sync function's own failure semantics
132	// (agents: null on failure; the rest: empty list).
133	async function readListAsync(method, key, fallback) {
134	  const reply = await ipc.call(method, {});
135	  if (reply && !reply.error) return reply.result?.[key] ?? null;
136	  return fallback();
137	}
138	
139	function agentsAsync() {
140	  return readListAsync('agent.list', 'agents', agents);
141	}
142	
143	function workspacesAsync() {
144	  return readListAsync('workspace.list', 'workspaces', workspaces).then((v) => v ?? []);
145	}
146	
147	function tabsAsync() {
148	  return readListAsync('tab.list', 'tabs', tabs).then((v) => v ?? []);
149	}
150	
151	function panesAsync() {
152	  return readListAsync('pane.list', 'panes', panes).then((v) => v ?? []);
153	}
154	
155	// Whether the Agents panel is in its grouped ("spaces") order. The sidebar's
156	// grouped/priority toggle persists `agent_panel_sort` into Herdr's config.toml
157	// and nowhere else — no CLI query, no event — so the file is the one place the
158	// mode can be read from. Cached briefly: the animator asks every tick.
159	const sortCache = { at: 0, grouped: true };
160	
161	function panelGrouped(now = Date.now()) {
162	  if (now - sortCache.at < 2000) return sortCache.grouped;
163	  let grouped = true;
164	  try {
165	    const mode = fs.readFileSync(herdrConfigPath(), 'utf8').match(/^\s*agent_panel_sort\s*=\s*"([^"]+)"/m)?.[1];
166	    grouped = mode !== 'priority';
167	  } catch {
168	    // An unreadable config reads as Herdr's default, which is grouped.
169	  }
170	  Object.assign(sortCache, { at: now, grouped });
171	  return grouped;
172	}
173	
174	function workspaceGet(workspaceId) {
175	  if (!workspaceId) return null;
176	  return call('workspace', 'get', workspaceId)?.result?.workspace ?? null;
177	}
178	
179	// Set and clear display tokens in one call. `tokens` maps name -> value, where
180	// null or undefined means "clear this one".
181	//
182	// Clearing matters as much as setting: this plugin encodes state in *which*
183	// token is present (one colour per token name, since Herdr's row styles are
184	// static), so a stale name left behind renders beside the current one.
185	function reportMetadata(paneId, source, tokens) {
186	  const args = ['pane', 'report-metadata', paneId, '--source', source];
187	  for (const [name, value] of Object.entries(tokens)) {
188	    if (value === null || value === undefined) args.push('--clear-token', name);
189	    else args.push('--token', `${name}=${value}`);
190	  }
191	  return call(...args) !== null;
192	}
193	
194	// Workspace-level twin of reportMetadata, for tokens the Spaces list renders.
195	function reportWorkspaceMetadata(workspaceId, source, tokens) {
196	  const args = ['workspace', 'report-metadata', workspaceId, '--source', source];
197	  for (const [name, value] of Object.entries(tokens)) {
198	    if (value === null || value === undefined) args.push('--clear-token', name);
199	    else args.push('--token', `${name}=${value}`);
200	  }
201	  return call(...args) !== null;
202	}
203	
204	// The socket API's token patch: name -> value, null meaning clear — the same
205	// contract the CLI flags encode, minus the process spawn.
206	function tokenPatch(tokens) {
207	  const patch = {};
208	  for (const [name, value] of Object.entries(tokens)) patch[name] = value ?? null;
209	  return patch;
210	}
211	
212	// Async twins of the two report calls, over the socket. The CLI wrapper costs
213	// a process spawn per write — 40-80ms on Windows — which turns any repaint
214	// touching every pane into seconds of visible catching-up. Socket calls run
215	// in parallel; a transport failure falls back to one CLI attempt so a machine
216	// where the socket misbehaves degrades to slow, not broken.
217	//
218	// A report to a pane or workspace that no longer exists is DONE, not failed.
219	// Herdr answers it with a not-found error, and that answer is final: the
220	// target is gone, and its tokens went with it. Reporting it as a failure put
221	// the target into the frame's retry backoff, which caps at a minute and never
222	// gives up — so every pane and workspace that ever closed was cleared again
223	// once a minute for the daemon's whole life, most of its IPC calls ended in
224	// errors, and each pending retry kept waking the scheduler (#21).
225	const GONE = new Set(['pane_not_found', 'workspace_not_found']);
226	const landed = (reply) => !reply.error || GONE.has(reply.error.code);
227	
228	async function reportMetadataAsync(paneId, source, tokens) {
229	  const reply = await ipc.call('pane.report_metadata', {
230	    pane_id: paneId,
231	    source,
232	    tokens: tokenPatch(tokens),
233	  });
234	  if (reply) return landed(reply);
235	  return reportMetadata(paneId, source, tokens);
236	}
237	
238	async function reportWorkspaceMetadataAsync(workspaceId, source, tokens) {
239	  const reply = await ipc.call('workspace.report_metadata', {
240	    workspace_id: workspaceId,
241	    source,
242	    tokens: tokenPatch(tokens),
243	  });
244	  if (reply) return landed(reply);
245	  return reportWorkspaceMetadata(workspaceId, source, tokens);
246	}
247	
248	module.exports = {
249	  pluginId,
250	  source,
251	  reloadConfig,
252	  configCheck,
253	  notify,
254	  call,
255	  panes,
256	  pane,
257	  paneProcessCwd,
258	  tabRowWidth,
259	  agents,
260	  tabs,
261	  workspaces,
262	  workspaceGet,
263	  agentsAsync,
264	  workspacesAsync,
265	  tabsAsync,
266	  panesAsync,
267	  panelGrouped,
268	  reportMetadata,
269	  reportWorkspaceMetadata,
270	  reportMetadataAsync,
271	  reportWorkspaceMetadataAsync,
272	  binary,
273	};
