832	// result inside SPACE_TOKENS, and a token outside that list is worse than a
833	// wrong colour: writeSpaceState sets every token it does not match to null, so
834	// one unknown name clears every state mark at once instead of mis-drawing a
835	// cell. The logos and the label are written after, from their own object, so
836	// such a row keeps its name and loses only what it was trying to say.
837	function spaceToken(display, vendor) {
838	  if (display === 'working') {
839	    return `space_working_${palette.brandVendors.includes(vendor) ? vendor : 'other'}`;
840	  }
841	  return `space_${display.startsWith('idle') ? 'idle' : display}`;
842	}
843	
844	function spaceMark(display) {
845	  if (display === 'none') return '·';
846	  return stateGlyph(display) ?? '·';
847	}
848	
849	// Which vendor tokens a workspace shows, as logo + name. They live on their
850	// own row under the workspace name, so there is room for the word — the logo
851	// alone reads as decoration until you have learned every mark.
852	//
853	// Exactly one named vendor → its own brand-coloured token. Anything else →
854	// everything packed into `multi` as one neutral cell, avoiding the forced `·`
855	// Herdr puts between cells.
856	function spaceLogoTokens(agents) {
857	  const out = { space_logo_other: null };
858	  for (const vendor of palette.brandVendors) out[`space_logo_${vendor}`] = null;
859	  const seen = new Set();
860	  const others = [];
861	  for (const a of agents) {
862	    if (!a.name || seen.has(a.name)) continue;
863	    seen.add(a.name);
864	    const logo = logoFor(a.name);
865	    // The vendor's own name is what a Spaces row has room for; the readable
866	    // one belongs beside a title, where there is a sentence to share the line
867	    // with.
868	    const label = logo ? `${logo} ${a.name}` : a.name;
869	    if (palette.brandVendors.includes(a.name)) out[`space_logo_${a.name}`] = label;
870	    else others.push(label);
871	  }
872	  if (others.length > 0) out.space_logo_other = others.join(' ');
873	  return out;
874	}
875	
876	// Chunked like the pane writes, and for the same reason: a workspace row now
877	// carries a token per branded vendor twice over — a working mark and a logo —
878	// which took the set past the sixteen a single report may hold. Herdr rejects
879	// an over-size patch WHOLE rather than truncating it, and a rejected patch is
880	// silent from the sidebar's side: the Spaces marks simply stop appearing.
881	function writeSpaceState(source, workspaceId, tokenName, glyph, logoTokens = {}, label = null) {
882	  const tokens = {};
883	  for (const name of SPACE_TOKENS) tokens[name] = name === tokenName ? glyph : null;
884	  Object.assign(tokens, logoTokens);
885	  // The Spaces panel's name column. Herdr's built-in `workspace` cell always
886	  // draws the real label and a plugin cannot style it; publishing the label as
887	  // a token of our own puts the whole row under the managed sidebar block, so
888	  // it takes the same colour rules as everything else there.
889	  tokens.space_label = label;
890	  return reportChunked(herdr.reportWorkspaceMetadataAsync, workspaceId, source, tokens);
891	}
892	
893	function clearSpaceState(source, workspaceId) {
894	  const tokens = {};
895	  for (const name of SPACE_TOKENS) tokens[name] = null;
896	  return reportChunked(herdr.reportWorkspaceMetadataAsync, workspaceId, source, tokens);
897	}
898	
899	// Everything this plugin painted, on every pane and workspace — the stop path.
900	// Two families stay: the title tokens, which the sidebar rows show the title
901	// THROUGH (clearing them blanks every entry, and a stopped plugin should leave
902	// a plain readable list, not an empty one), and the sort keys, which a view
903	// may still be ordering by (a frozen order beats a collapsed one). `purge`
904	// takes those too, plus the vendor logo agent-icons.js writes: the uninstall
905	// path, where the blocks that render them are about to go.
906	async function clearAll(source, { purge = false } = {}) {
907	  const names = purge
908	    ? [...OWNED_TOKENS, 'harness_logo']
909	    : OWNED_TOKENS.filter((name) => !name.startsWith('title_') && name !== 'sort_key' && name !== 'ws_key');
910	  await sweepOrphans(source, new Set(), names);
911	  await Promise.all(
912	    (await herdr.workspacesAsync())
913	      .filter((ws) => typeof ws.workspace_id === 'string')
914	      .map((ws) => clearSpaceState(source, ws.workspace_id)),
915	  );
916	}
917	
918	module.exports = {
919	  clearAll,
920	  stateTokens,
921	  tokenDelta,
922	  writeTokens,
923	  STATES,
924	  LOGO_TOKENS,
925	  LEGACY_LOGO_TOKENS,
926	  baseState,
927	  SPACE_TOKENS,
928	  SPACE_PRIORITY,
929	  spaceToken,
930	  // Pure, and exported for tools/check.js: the row's name is decided here, and
931	  // the invariant that a vendor we can name never goes nameless has to run the
932	  // real pair rather than a copy of the stripping regex.
933	  stripVendorPulse,
934	  vendorTitle,
935	  INDENT,
936	  CHILD_INDENT,
937	  SPLIT_INDENT,
938	  INDENTS,
939	  LOCK,
940	  STOP,
941	  STALLED_MS,
942	  HUNG_FRAME_MS,
943	  daemonStatus,
944	  waitForExit,
945	  terminate,
946	  snapshot,
947	  labels,
948	  composeLine,
949	  clearState,
950	  spaceMark,
951	  spaceLogoTokens,
952	  writeSpaceState,
953	  clearSpaceState,
954	  groupBoundaries,
955	  trimGroupPrefix,
956	  writeGroups,
957	  clearGroups,
958	  sweepOrphans,
959	  OWNED_TOKENS,
960	};
