31	const TAB_BAR = identity.markers('tab-bar');
32	const BLOCK_START = TAB_BAR.start;
33	const BLOCK_END = TAB_BAR.end;
34	// The tab-bar block edits bare keys inside `[ui]`, so it must sit in that
35	// table. These two bring their own table headers and are appended at the end
36	// of the file instead: a header dropped in front of another table's bare keys
37	// silently adopts them (`theme.custom.name` and friends — Herdr then reports
38	// them as unknown keys).
39	const THEME = identity.markers('theme');
