174	function block(requestedInterval = 6) {
175	  // Herdr's own floor is one second, and a one-second interval cannot carry a
176	  // shorter timeout, so two is the smallest interval this can honestly write.
177	  const intervalSeconds = Math.max(2, requestedInterval);
178	  const timeoutSeconds = Math.max(1, intervalSeconds - TIMEOUT_MARGIN_SECONDS);
179	  const cache = path.join(stateRoot, 'tabbar.txt');
180	  // TOML literal strings (single quotes) keep Windows backslashes out of the
181	  // escape parser. cmd's `type` needs backslashes — forward slashes read as
182	  // switches — so the path is NOT posix()ed on Windows.
183	  const command = process.platform === 'win32' ? `type "${cache}"` : `cat "${posix(cache)}"`;
184	  return [
185	    BLOCK_START,
186	    'tab_bar_right_separator = " · "',
187	    'tab_bar_right = [',
188	    `  { type = 'command', command = '${command}', interval_seconds = ${intervalSeconds}, timeout_seconds = ${timeoutSeconds} },`,
189	    ']',
190	    BLOCK_END,
191	  ].join('\n');
192	}
