108	     * git branch and extension statuses from setStatus(). Context usage is on
109	     * ctx.getContextUsage(), token stats on ctx.sessionManager.getEntries(), model info on ctx.model.
110	     */
111	    setFooter(factory: ((tui: TUI, theme: Theme, footerData: ReadonlyFooterDataProvider) => Component & {
112	        dispose?(): void;
